def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        return min(budget, 20.0)

    strongest_name = None
    strongest_score = -1.0
    strongest_prev_bid = 0.0
    strongest_budget = 0.0

    for agent_id, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        prev_bid = prev.get('bid')
        if prev_bid is None:
            prev_bid = 0.0
        opp_budget = opp.get('budget', 0.0)
        score = prev_bid + 0.15 * opp_budget
        if score > strongest_score:
            strongest_score = score
            strongest_name = agent_id
            strongest_prev_bid = prev_bid
            strongest_budget = opp_budget

    competitors = len(alive) + 1
    units = supply / float(WATER_REQ)
    tight_supply = units < competitors
    very_tight = units < max(1.5, competitors - 1)

    emergency = hp <= 3 or no_water_days >= 2
    pressured = hp <= 5 or no_water_days >= 1

    bid = 0.0

    if strongest_name == 'Bob':
        if emergency:
            bid = max(63.0, strongest_prev_bid + 2.0)
        elif very_tight:
            bid = max(60.0, strongest_prev_bid + 1.2)
        elif tight_supply:
            bid = max(54.0, strongest_prev_bid + 0.8)
        else:
            bid = 41.0 if not pressured else 52.0
    else:
        if emergency:
            bid = 58.0
        elif tight_supply:
            bid = 44.0
        else:
            bid = 26.0

    if strongest_budget < 35:
        bid = min(bid, strongest_prev_bid + 0.5 if strongest_prev_bid > 0 else 28.0)

    if budget < bid:
        if emergency:
            bid = budget
        else:
            bid = min(budget, max(0.0, budget * 0.72))

    if not emergency and budget < DAILY_SALARY * 2:
        bid = min(bid, max(18.0, budget * 0.45))

    if hp >= 8 and not tight_supply:
        bid = min(bid, 36.0)

    if bid < 0.0:
        bid = 0.0
    if bid > budget:
        bid = budget
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return float(min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from immediate previous_trace
    opp_prev_bids = []
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                opp_prev_bids.append((opp_id, float(b)))
            except Exception:
                pass

    # Identify the most aggressive opponent yesterday (likely Alex)
    if opp_prev_bids:
        opp_prev_bids.sort(key=lambda x: x[1], reverse=True)
        top_opp_id, top_bid = opp_prev_bids[0]
    else:
        top_opp_id, top_bid = None, 0.0

    # Pressure estimate: if top bid was high, we must bid enough to beat it.
    # Use a slightly undercut strategy to win without overpaying.
    # Typical Alex behavior: avg ~65.5, max ~70.
    if top_bid >= DAILY_SALARY * 0.75:
        target = top_bid - 2.0
    elif top_bid > 0:
        target = max(top_bid * 0.9, DAILY_SALARY * 0.5)
    else:
        target = DAILY_SALARY * 0.55

    # If supply is low, water is more scarce; increase bid slightly.
    # supply in [15,25]; map to scarcity factor.
    scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    target = target * (1.0 + 0.12 * scarcity)

    # If my hp is low or I'm accumulating no-water days, bid more to secure survival.
    if my_hp <= 2.5 or my_no_water_days >= 2:
        target = max(target, DAILY_SALARY * 0.85)
    elif my_hp <= 4.0:
        target = max(target, DAILY_SALARY * 0.65)

    # Budget cap: never exceed what we can pay.
    bid = float(min(my_budget, target))

    # Also avoid bidding trivially low when we have budget and need water.
    min_reasonable = DAILY_SALARY * 0.35
    if my_budget > min_reasonable and bid < min_reasonable and my_hp > 2.5:
        bid = min_reasonable

    # Ensure non-negative.
    if bid < 0.0:
        bid = 0.0

    return bid
